import React, { useEffect, useState } from 'react';
import { Modal, Button, Form, Spinner, Alert } from 'react-bootstrap';

function ProductsList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const [showModal, setShowModal] = useState(false);
  const [currentProduct, setCurrentProduct] = useState(null);

  const [formData, setFormData] = useState({
    nom: '',
    referencia: '',
    descripcio: '',
    quantitat: ''
  });

  const token = localStorage.getItem('token');

  /* -----------------------------
     DEBUG TOKEN (puedes borrar luego)
  ------------------------------ */
  console.log('JWT TOKEN:', token);

  /* -----------------------------
     OBTENER PRODUCTOS
  ------------------------------ */
  const fetchProducts = async () => {
    try {
      const res = await fetch('http://localhost/api/productes', {
        headers: {
          Accept: 'application/json'
        }
      });

      const data = await res.json();
      setProducts(data.dades || []);
    } catch {
      setError('Error carregant productes');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  /* -----------------------------
     EDITAR PRODUCTE
  ------------------------------ */
  const openEditModal = (product) => {
    setCurrentProduct(product);
    setFormData({
      nom: product.nom,
      referencia: product.referencia,
      descripcio: product.descripcio,
      quantitat: product.quantitat
    });
    setShowModal(true);
  };

  const saveProduct = async () => {
    try {
      const res = await fetch(`http://localhost/api/productes/${currentProduct.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(formData)
      });

      if (!res.ok) throw new Error();

      setProducts(products.map(p =>
        p.id === currentProduct.id ? { ...p, ...formData } : p
      ));

      setShowModal(false);
    } catch {
      alert('Error actualitzant el producte');
    }
  };

  /* -----------------------------
     ELIMINAR PRODUCTE
  ------------------------------ */
  const deleteProduct = async (id) => {
    if (!window.confirm('Vols eliminar aquest producte?')) return;

    try {
      const res = await fetch(`http://localhost/api/productes/${id}`, {
        method: 'DELETE',
        headers: {
          'Accept': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });

      if (!res.ok) throw new Error();

      setProducts(products.filter(p => p.id !== id));
    } catch {
      alert('Error eliminant el producte');
    }
  };

  /* -----------------------------
     UI
  ------------------------------ */
  if (loading) return <Spinner animation="border" />;
  if (error) return <Alert variant="danger">{error}</Alert>;

  return (
    <>
      <h2 className="mb-4">Productes</h2>

      <div className="row">
        {products.map(product => (
          <div key={product.id} className="col-md-4 mb-3">
            <div className="card h-100">
              <div className="card-body">
                <h5>{product.nom}</h5>
                <p>{product.descripcio}</p>
                <p><strong>Referència:</strong> {product.referencia}</p>
                <p><strong>Quantitat:</strong> {product.quantitat}</p>

                <Button
                  variant="warning"
                  size="sm"
                  className="me-2"
                  onClick={() => openEditModal(product)}
                >
                  Editar
                </Button>

                <Button
                  variant="danger"
                  size="sm"
                  onClick={() => deleteProduct(product.id)}
                >
                  Eliminar
                </Button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* MODAL EDITAR */}
      <Modal show={showModal} onHide={() => setShowModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Editar producte</Modal.Title>
        </Modal.Header>

        <Modal.Body>
          <Form>
            <Form.Group className="mb-2">
              <Form.Label>Nom</Form.Label>
              <Form.Control
                value={formData.nom}
                onChange={e => setFormData({ ...formData, nom: e.target.value })}
              />
            </Form.Group>

            <Form.Group className="mb-2">
              <Form.Label>Referència</Form.Label>
              <Form.Control
                value={formData.referencia}
                onChange={e => setFormData({ ...formData, referencia: e.target.value })}
              />
            </Form.Group>

            <Form.Group className="mb-2">
              <Form.Label>Descripció</Form.Label>
              <Form.Control
                value={formData.descripcio}
                onChange={e => setFormData({ ...formData, descripcio: e.target.value })}
              />
            </Form.Group>

            <Form.Group>
              <Form.Label>Quantitat</Form.Label>
              <Form.Control
                type="number"
                value={formData.quantitat}
                onChange={e => setFormData({ ...formData, quantitat: e.target.value })}
              />
            </Form.Group>
          </Form>
        </Modal.Body>

        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Cancel·lar
          </Button>
          <Button variant="primary" onClick={saveProduct}>
            Guardar
          </Button>
        </Modal.Footer>
      </Modal>
    </>
  );
}

export default ProductsList;
